/**
 * Record an entry in the audit trail. Best-effort: a logging failure must never
 * break the underlying operation, so errors are swallowed (logged to console).
 */
const logAudit = async ({ action, entityType, entityId, actor, summary, changes, snapshot }) => {
    try {
        await execQuery(
            `INSERT INTO audit_trail (action, entity_type, entity_id, actor, summary, changes, snapshot)
             VALUES (?, ?, ?, ?, ?, ?, ?)`,
            [
                action,
                entityType,
                entityId != null ? String(entityId) : null,
                actor || null,
                summary || null,
                changes ? JSON.stringify(changes) : null,
                snapshot ? JSON.stringify(snapshot) : null,
            ]
        );
    } catch (e) {
        console.error('   ⚠️ Failed to write audit_trail entry:', e && e.message);
    }
};

// ============================================================
// RBAC (role-based access control)
// ============================================================
// The dashboard authenticates users against GLPI; there is no local user store.
// These tables map a GLPI username -> a role, and a role -> a permission map so
// the dashboard can decide which modules a user may view and which actions
// (execute/edit/delete) they may perform. Permissions are stored as JSON so the
// module/action set can grow without schema changes.
//
// Modules: 'audit_records' (dashboard, asset review, discrepancy, audit trail,
// report, scanned view/edit/delete) and 'forms' (the Forms OCR module).
// Actions:  view, execute, edit, delete.

const ensureRbacTables = async () => {
    const rolesDdl = `
        CREATE TABLE IF NOT EXISTS rbac_roles (
            id INT AUTO_INCREMENT PRIMARY KEY,
            name VARCHAR(80) NOT NULL UNIQUE,
            is_admin TINYINT(1) NOT NULL DEFAULT 0,
            permissions LONGTEXT NULL,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
        )
    `;
    const userRolesDdl = `
        CREATE TABLE IF NOT EXISTS rbac_user_roles (
            id INT AUTO_INCREMENT PRIMARY KEY,
            username VARCHAR(150) NOT NULL UNIQUE,
            role_id INT NOT NULL,
            updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
            KEY idx_role (role_id)
        )
    `;
    try {
        await pool.query(rolesDdl);
        await pool.query(userRolesDdl);
        console.log('   ✅ rbac_roles / rbac_user_roles tables ready');
        await seedDefaultRoles();
    } catch (e) {
        console.error('   ❌ Failed to ensure RBAC tables:', e && e.message);
    }
};

// Seed a sensible starter set of roles ONLY when none exist yet, so an admin
// can immediately assign users. Never overwrites roles an admin has edited.
const seedDefaultRoles = async () => {
    try {
        const [rows] = await execQuery('SELECT COUNT(*) AS c FROM rbac_roles');
        if (rows[0] && Number(rows[0].c) > 0) return;

        const P = (audit, forms) => JSON.stringify({ audit_records: audit, forms });
        const none = { view: 0, execute: 0, edit: 0, delete: 0 };
        const seeds = [
            ['Administrator', 1, P({ view: 1, execute: 1, edit: 1, delete: 1 }, { view: 1, execute: 1, edit: 1, delete: 1 })],
            ['Editor', 0, P({ view: 1, execute: 1, edit: 1, delete: 0 }, { view: 1, execute: 1, edit: 1, delete: 0 })],
            ['Viewer', 0, P({ view: 1, execute: 0, edit: 0, delete: 0 }, none)],
            ['Forms Operator', 0, P(none, { view: 1, execute: 1, edit: 1, delete: 0 })],
        ];
        for (const [name, isAdmin, perms] of seeds) {
            await execQuery(
                'INSERT INTO rbac_roles (name, is_admin, permissions) VALUES (?, ?, ?)',
                [name, isAdmin, perms]
            );
        }
        console.log('   ✅ Seeded default RBAC roles (Administrator, Editor, Viewer, Forms Operator)');
    } catch (e) {
        console.error('   ⚠️ Failed to seed default roles:', e && e.message);
    }
};
ensureRbacTables();

// Parse a role's permissions JSON safely into an object.
const parsePerms = (raw) => {
    if (!raw) return {};
    try { return typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { return {}; }
};

