// ============================================================
// OFFLINE OCR + PDF + SIGNATURE-DETECTION PIPELINE
// ============================================================
// All engines are lazy-loaded so the server still boots (and forms still upload)
// if a dependency isn't installed. Everything is wired to LOCAL files only — no
// network/CDN — so it works on an air-gapped LAN.

// Tuning knobs (env-overridable).
const OCR_LANG = process.env.OCR_LANG || 'eng';
// Folder that holds <lang>.traineddata (and optionally the core wasm + worker).
const OCR_ASSETS_DIR = process.env.OCR_LANG_PATH || process.env.OCR_ASSETS_DIR
    || path.join(__dirname, '..', 'deploy', 'ocr');
const OCR_LEGACY_DIR = path.join(__dirname, '..', 'ocr-lang'); // older default
const SIG_INK_THRESHOLD = Number(process.env.SIG_INK_THRESHOLD || 0.05); // 5% dark pixels
const SIG_GREY_THRESHOLD = Number(process.env.SIG_GREY_THRESHOLD || 150); // 0-255

// Lazy module holders.
let Tesseract = null;
try { Tesseract = require('tesseract.js'); console.log('   ✅ tesseract.js loaded (OCR enabled)'); }
catch (e) { console.warn('   ⚠️ tesseract.js not installed — OCR disabled (forms still upload).'); }

let pdfParse = null;
try { pdfParse = require('pdf-parse'); console.log('   ✅ pdf-parse loaded (native-PDF text)'); }
catch (e) { console.warn('   ⚠️ pdf-parse not installed — native-PDF text extraction disabled.'); }

let sharpLib = null;
try { sharpLib = require('sharp'); console.log('   ✅ sharp loaded (signature detection)'); }
catch (e) { console.warn('   ⚠️ sharp not installed — signature detection disabled.'); }

// pdf-to-img is ESM-only; load it on demand via dynamic import().
let pdfToImg = null;
const getPdfToImg = async () => {
    if (pdfToImg) return pdfToImg;
    try { pdfToImg = await import('pdf-to-img'); return pdfToImg; }
    catch (e) { console.warn('   ⚠️ pdf-to-img not available — scanned-PDF rasterisation disabled:', e && e.message); return null; }
};

// Resolve strictly-local Tesseract asset paths so nothing is ever fetched from a
// CDN. langPath must contain <lang>.traineddata; core/worker default to the local
// installed packages (already offline in Node) but can be overridden.
const resolveOcrPaths = () => {
    const paths = {};
    if (fs.existsSync(path.join(OCR_ASSETS_DIR, `${OCR_LANG}.traineddata`))) paths.langPath = OCR_ASSETS_DIR;
    else if (fs.existsSync(path.join(OCR_LEGACY_DIR, `${OCR_LANG}.traineddata`))) paths.langPath = OCR_LEGACY_DIR;
    paths.corePath = process.env.OCR_CORE_PATH || (() => {
        try { return path.dirname(require.resolve('tesseract.js-core/package.json')); } catch (e) { return undefined; }
    })();
    paths.workerPath = process.env.OCR_WORKER_PATH || (() => {
        try { return require.resolve('tesseract.js/src/worker-script/node/index.js'); } catch (e) { return undefined; }
    })();
    return paths;
};
let _ocrPathsLogged = false;

// Create a fully-local Tesseract worker. Returns null if OCR isn't available.
const createOcrWorker = async () => {
    if (!Tesseract) return null;
    const p = resolveOcrPaths();
    if (!_ocrPathsLogged) {
        console.log(`   🔤 OCR paths — lang:${p.langPath || '(default)'} core:${p.corePath || '(default)'} worker:${p.workerPath ? 'local' : '(default)'}`);
        _ocrPathsLogged = true;
    }
    const opts = { gzip: false, workerBlobURL: false, cacheMethod: 'none' };
    if (p.langPath) opts.langPath = p.langPath;
    if (p.corePath) opts.corePath = p.corePath;
    if (p.workerPath) opts.workerPath = p.workerPath;
    return Tesseract.createWorker(OCR_LANG, 1, opts);
};

// Flatten a Tesseract result into a flat list of words with bounding boxes,
// tolerating both the legacy data.words array and the v5 blocks hierarchy.
const extractWords = (data) => {
    const out = [];
    const push = (w) => { if (w && w.text && w.bbox) out.push({ text: String(w.text), bbox: w.bbox, confidence: w.confidence }); };
    if (Array.isArray(data.words) && data.words.length) { data.words.forEach(push); return out; }
    (data.blocks || []).forEach((b) => (b.paragraphs || []).forEach((pg) =>
        (pg.lines || []).forEach((ln) => (ln.words || []).forEach(push))));
    return out;
};

// OCR an image → plain text.
const ocrText = async (imagePath) => {
    if (!Tesseract || !imagePath) return '';
    let worker = null;
    try {
        worker = await createOcrWorker();
        const { data } = await worker.recognize(imagePath);
        return (data && data.text ? data.text : '').trim();
    } catch (e) { console.error('   ⚠️ OCR failed:', e && e.message); return ''; }
    finally { if (worker) { try { await worker.terminate(); } catch (e) {} } }
};

// OCR an image → { text, words } (words carry bounding boxes for sig detection).
const ocrWords = async (imagePath) => {
    if (!Tesseract || !imagePath) return { text: '', words: [] };
    let worker = null;
    try {
        worker = await createOcrWorker();
        const { data } = await worker.recognize(imagePath, {}, { text: true, blocks: true });
        return { text: (data && data.text ? data.text : '').trim(), words: extractWords(data || {}) };
    } catch (e) { console.error('   ⚠️ OCR (words) failed:', e && e.message); return { text: '', words: [] }; }
    finally { if (worker) { try { await worker.terminate(); } catch (e) {} } }
};
// Back-compat alias used before the pipeline rewrite.
const runOcr = ocrText;

// Extract text from a native/digital PDF (returns '' for scanned/imaged PDFs).
const pdfTextOf = async (pdfPath) => {
    if (!pdfParse) return '';
    try {
        const buf = fs.readFileSync(pdfPath);
        const res = await pdfParse(buf);
        return (res && res.text ? res.text : '').trim();
    } catch (e) { console.error('   ⚠️ pdf-parse failed:', e && e.message); return ''; }
};

// Rasterise page 1 of a PDF to a high-res PNG on disk. Returns the PNG path or null.
const rasterizePdfPage1 = async (pdfPath, outPngPath) => {
    const mod = await getPdfToImg();
    if (!mod) return null;
    try {
        const pdf = mod.pdf || (mod.default && mod.default.pdf) || mod.default;
        const doc = await pdf(pdfPath, { scale: 3 });
        let buf = null;
        if (typeof doc.getPage === 'function') buf = await doc.getPage(1);
        else { for await (const page of doc) { buf = page; break; } }
        if (!buf) return null;
        fs.writeFileSync(outPngPath, buf);
        return outPngPath;
    } catch (e) { console.error('   ⚠️ pdf-to-img rasterise failed:', e && e.message); return null; }
};

// ---- Signature detection ----

// Group words into text lines (sorted top-to-bottom, left-to-right).
const buildLines = (words) => {
    if (!words.length) return [];
    const heights = words.map((w) => w.bbox.y1 - w.bbox.y0).filter((h) => h > 0).sort((a, b) => a - b);
    const medH = heights[Math.floor(heights.length / 2)] || 12;
    const sorted = words.slice().sort((a, b) => (a.bbox.y0 - b.bbox.y0) || (a.bbox.x0 - b.bbox.x0));
    const lines = [];
    for (const w of sorted) {
        const cy = (w.bbox.y0 + w.bbox.y1) / 2;
        let line = lines.find((l) => Math.abs(l.cy - cy) < medH * 0.7);
        if (!line) { line = { cy, words: [] }; lines.push(line); }
        line.words.push(w);
        line.cy = (line.cy * (line.words.length - 1) + cy) / line.words.length;
    }
    return lines.map((l) => {
        const ws = l.words.sort((a, b) => a.bbox.x0 - b.bbox.x0);
        return {
            text: ws.map((w) => w.text).join(' ').toLowerCase().replace(/\s+/g, ' ').trim(),
            words: ws,
            bbox: {
                x0: Math.min(...ws.map((w) => w.bbox.x0)), y0: Math.min(...ws.map((w) => w.bbox.y0)),
                x1: Math.max(...ws.map((w) => w.bbox.x1)), y1: Math.max(...ws.map((w) => w.bbox.y1)),
            },
        };
    });
};

// Find the bounding box of an anchor phrase within the page's lines.
const findAnchorBox = (lines, anchors, sectionHint, imgH) => {
    const norm = (s) => s.toLowerCase().replace(/\s+/g, ' ').trim();
    let candidates = lines;
    if (sectionHint && sectionHint.region === 'bottom' && imgH) {
        const cutoff = imgH * (1 - (sectionHint.fraction || 0.45));
        candidates = lines.filter((l) => l.bbox.y0 >= cutoff);
        if (!candidates.length) candidates = lines; // fall back if nothing matched
    }
    for (const phrase of anchors.map(norm)) {
        const tokens = phrase.split(' ');
        for (const line of candidates) {
            if (line.text.includes(phrase)) {
                const hit = line.words.filter((w) => tokens.some((t) => w.text.toLowerCase().includes(t)));
                const box = hit.length ? {
                    x0: Math.min(...hit.map((w) => w.bbox.x0)), y0: Math.min(...hit.map((w) => w.bbox.y0)),
                    x1: Math.max(...hit.map((w) => w.bbox.x1)), y1: Math.max(...hit.map((w) => w.bbox.y1)),
                } : line.bbox;
                return { bbox: box, matched: phrase };
            }
        }
    }
    return null;
};

// Compute an ROI (where the ink should be) from an anchor bbox.
const computeRoi = (anchor, roiCfg, imgW, imgH) => {
    const cfg = roiCfg || { direction: 'above', widthFactor: 2.4, heightFactor: 1.6 };
    const aw = Math.max(1, anchor.x1 - anchor.x0), ah = Math.max(1, anchor.y1 - anchor.y0);
    const w = Math.round(aw * (cfg.widthFactor || 2.4));
    const h = Math.round(ah * (cfg.heightFactor || 1.6));
    const cx = (anchor.x0 + anchor.x1) / 2;
    let left, top;
    if (cfg.direction === 'right') { left = anchor.x1 + Math.round(ah * 0.4); top = Math.round(anchor.y0 - ah * 0.3); }
    else { left = Math.round(cx - w / 2); top = Math.round(anchor.y0 - h - ah * 0.3); } // 'above'
    left = Math.max(0, Math.min(left, imgW - 1));
    top = Math.max(0, Math.min(top, imgH - 1));
    const width = Math.max(1, Math.min(w, imgW - left));
    const height = Math.max(1, Math.min(h, imgH - top));
    return { left, top, width, height };
};

// Crop an ROI, threshold it, and return the dark-pixel (ink) density 0..1.
const inkDensity = async (imagePath, roi) => {
    if (!sharpLib) return 0;
    try {
        const { data, info } = await sharpLib(imagePath)
            .extract({ left: roi.left, top: roi.top, width: roi.width, height: roi.height })
            .greyscale().threshold(SIG_GREY_THRESHOLD).raw().toBuffer({ resolveWithObject: true });
        const ch = info.channels || 1;
        let dark = 0; const total = info.width * info.height;
        for (let i = 0; i < data.length; i += ch) if (data[i] < 128) dark++;
        return total ? dark / total : 0;
    } catch (e) { console.error('   ⚠️ inkDensity failed:', e && e.message); return 0; }
};

// Run the full signature detection for a template against a raster image + words.
const detectSignatures = async (imagePath, words, imgW, imgH, template) => {
    const results = [];
    if (!template || !Array.isArray(template.signers) || !template.signers.length) return results;
    const lines = buildLines(words);
    for (const signer of template.signers) {
        const anchor = findAnchorBox(lines, signer.anchors, template.sectionHint, imgH);
        if (!anchor) { results.push({ label: signer.label, anchor_found: 0, detected: 0, ink_density: null, roi: null }); continue; }
        const roi = computeRoi(anchor.bbox, template.roi, imgW, imgH);
        const density = await inkDensity(imagePath, roi);
        results.push({
            label: signer.label, anchor_found: 1,
            detected: density > SIG_INK_THRESHOLD ? 1 : 0,
            ink_density: Number(density.toFixed(4)), roi,
        });
    }
    return results;
};

// Image dimensions via sharp (needed to map coordinates + clamp ROIs).
const imageSize = async (imagePath) => {
    if (!sharpLib) return { width: 0, height: 0 };
    try { const m = await sharpLib(imagePath).metadata(); return { width: m.width || 0, height: m.height || 0 }; }
    catch (e) { return { width: 0, height: 0 }; }
};

// ---- Form templates (signature config keyed by form_type) ----
const FORM_TEMPLATES = {
    form1: {
        match: ['form 1', 'form1', 'new computer and network user'],
        sectionHint: { region: 'bottom', fraction: 0.45 }, // "Job Complete Acknowledge"
        signers: [
            { label: 'Dept. Manager', anchors: ['dept. manager signature', 'department manager', 'dept manager'] },
            { label: 'ITS Staff', anchors: ['its staff signature', 'its staff'] },
        ],
        requiredForComplete: ['ITS Staff'],
        roi: { direction: 'above', widthFactor: 2.4, heightFactor: 1.6 },
    },
    default: {
        match: [],
        sectionHint: null,
        signers: [{ label: 'Signature', anchors: ['signature', 'signed', 'approved by', 'tandatangan'] }],
        requiredForComplete: [],
        roi: { direction: 'above', widthFactor: 2.6, heightFactor: 1.6 },
    },
};
const resolveTemplate = (formType) => {
    const t = (formType || '').toString().toLowerCase();
    for (const key of Object.keys(FORM_TEMPLATES)) {
        if (key === 'default') continue;
        if (FORM_TEMPLATES[key].match.some((m) => t.includes(m))) return FORM_TEMPLATES[key];
    }
    return FORM_TEMPLATES.default;
};

