// Resolve the effective permissions for one username. Returns the assigned role
// (or null) and a permission map. is_admin roles resolve to all-true. The
// dashboard calls this once per page to decide menu/link visibility and actions.
app.get('/api/rbac/resolve/:username', async (req, res) => {
    const username = req.params.username;
    try {
        const [rows] = await execQuery(
            `SELECT r.id AS role_id, r.name AS role_name, r.is_admin, r.permissions
               FROM rbac_user_roles ur JOIN rbac_roles r ON r.id = ur.role_id
              WHERE ur.username = ? LIMIT 1`,
            [username]
        );
        if (rows.length === 0) {
            return res.status(200).json({ username, role_id: null, role_name: null, is_admin: 0, permissions: {} });
        }
        const row = rows[0];
        return res.status(200).json({
            username,
            role_id: row.role_id,
            role_name: row.role_name,
            is_admin: row.is_admin ? 1 : 0,
            permissions: parsePerms(row.permissions),
        });
    } catch (e) {
        console.error('   ❌ rbac resolve error:', e && e.message);
        return res.status(500).json({ message: 'Failed to resolve permissions', error: e.message });
    }
});

// List all roles with parsed permissions.
app.get('/api/rbac/roles', async (req, res) => {
    try {
        const [rows] = await execQuery('SELECT id, name, is_admin, permissions FROM rbac_roles ORDER BY is_admin DESC, name ASC');
        const roles = rows.map((r) => ({ id: r.id, name: r.name, is_admin: r.is_admin ? 1 : 0, permissions: parsePerms(r.permissions) }));
        return res.status(200).json({ data: roles });
    } catch (e) {
        return res.status(500).json({ message: 'Failed to list roles', error: e.message });
    }
});

// Create a role.
app.post('/api/rbac/roles', async (req, res) => {
    const { name, is_admin, permissions } = req.body || {};
    if (!name || !String(name).trim()) return res.status(400).json({ message: 'Role name is required' });
    try {
        const permJson = permissions ? JSON.stringify(permissions) : JSON.stringify({});
        const [result] = await execQuery(
            'INSERT INTO rbac_roles (name, is_admin, permissions) VALUES (?, ?, ?)',
            [String(name).trim(), is_admin ? 1 : 0, permJson]
        );
        return res.status(201).json({ message: 'Role created', id: result.insertId });
    } catch (e) {
        if (e.code === 'ER_DUP_ENTRY') return res.status(409).json({ message: 'A role with that name already exists' });
        return res.status(500).json({ message: 'Failed to create role', error: e.message });
    }
});

// Update a role's name / admin flag / permissions.
app.put('/api/rbac/roles/:id', async (req, res) => {
    const { id } = req.params;
    const { name, is_admin, permissions } = req.body || {};
    try {
        const permJson = permissions ? JSON.stringify(permissions) : null;
        await execQuery(
            `UPDATE rbac_roles
                SET name = COALESCE(?, name),
                    is_admin = COALESCE(?, is_admin),
                    permissions = COALESCE(?, permissions)
              WHERE id = ?`,
            [name != null ? String(name).trim() : null, is_admin != null ? (is_admin ? 1 : 0) : null, permJson, id]
        );
        return res.status(200).json({ message: 'Role updated', id: Number(id) });
    } catch (e) {
        if (e.code === 'ER_DUP_ENTRY') return res.status(409).json({ message: 'A role with that name already exists' });
        return res.status(500).json({ message: 'Failed to update role', error: e.message });
    }
});

