// 1. GET: Retrieve a single asset by asset_tag
// Look up an asset by tag via a QUERY STRING (not a path segment). Asset tags
// can contain slashes, spaces and parentheses (e.g. "PE/MYY-HQ/CHW/0009 (A)");
// putting those in the URL path makes the encoded slashes route to 404. The
// query-string form carries any tag safely. This route is declared before the
// "/api/assets/:assetTag" path route so "/api/assets?asset_tag=..." matches here.
app.get("/api/assets", async (req, res) => {
    const assetTag = req.query.asset_tag || req.query.tag;
    console.log(`\n➡️ GET /api/assets?asset_tag=${assetTag}`);

    if (!assetTag) {
        return res.status(400).json({ message: "asset_tag query parameter is required" });
    }

    const query = "SELECT id, asset_tag, category, assigned_user, location_id, date_buy FROM assets WHERE asset_tag = ?";
    try {
        const [rows] = await execQuery(query, [assetTag]);
        if (rows.length === 0) {
            console.log(`   ⬅️ STATUS: 404 Not Found (Asset: ${assetTag})`);
            return res.status(404).json({ message: "Asset not found" });
        }
        console.log(`   ⬅️ STATUS: 200 OK. Asset ID: ${rows[0].id}`);
        return res.status(200).json(rows[0]);
    } catch (error) {
        console.error("   ❌ ERROR:", error.message);
        return res.status(500).json({ message: "Error retrieving asset data", error: error.message });
    }
});

