// 2. POST: Submit Audit Results
app.post('/api/audit/submit', async (req, res) => {
    const data = req.body || {};

    // LOG: Incoming request and payload data (enhanced for debugging)
    const timestamp = new Date().toISOString();
    const clientIp = req.headers['x-forwarded-for'] || (req.socket && req.socket.remoteAddress) || req.ip || 'unknown';
    console.log(`\n[${timestamp}] POST /api/audit/submit from ${clientIp}`);
    try { console.log('   HEADERS:', JSON.stringify(req.headers)); } catch (e) { console.log('   HEADERS: [unserializable]'); }
    try { console.log('   RAW BODY:', JSON.stringify(req.body)); } catch (e) { console.log('   RAW BODY: [unserializable]'); }
    console.log('   BODY TYPE:', typeof req.body);

    // Grab fields from the incoming body
    let {
        audit_id, asset_id, asset_internal_id, asset_found, actual_user, actual_location_id,
        is_physical_good, is_patch_latest, is_endpoint_latest,
        is_monitor_working, is_ups_working, led_normal, no_fault, fa_tagging, additional_info, checked_by
    } = data;

    // --- Resolve which asset (assets.id) this result belongs to ---
    // Preferred: an explicit internal id the caller already resolved. GLPI ids
    // are NOT unique across item types and can collide with internal ids, so
    // resolving by glpi_id could attach the result to the WRONG asset and
    // overwrite another row — making records appear to randomly "go missing".
    // asset_internal_id is unambiguous and avoids that.
    try {
        if (asset_internal_id != null) {
            const [rows] = await execQuery('SELECT id FROM assets WHERE id = ?', [asset_internal_id]);
            if (rows.length === 0) {
                console.error(`   ❌ asset_internal_id ${asset_internal_id} not found`);
                return res.status(404).json({ message: 'Asset not found', asset_internal_id });
            }
            asset_id = rows[0].id;
            console.log(`   ✅ Using internal asset id ${asset_id}`);
        } else if (asset_id != null) {
            // Legacy path (older app builds send a GLPI id as asset_id).
            const [rows] = await execQuery('SELECT id FROM assets WHERE glpi_id = ? ORDER BY id LIMIT 1', [asset_id]);
            if (rows.length > 0) {
                console.log(`   🔄 Mapped GLPI ID ${asset_id} to Internal ID ${rows[0].id}`);
                asset_id = rows[0].id;
            } else {
                const [checkId] = await execQuery('SELECT id FROM assets WHERE id = ?', [asset_id]);
                if (checkId.length === 0) {
                    console.error(`   ❌ Asset ID ${asset_id} not found (as glpi_id or internal id)`);
                    return res.status(404).json({ message: 'Asset not found' });
                }
            }
        }
    } catch (err) {
        console.error('   ❌ ERROR resolving asset id:', err.message);
        return res.status(500).json({ message: 'Failed to resolve asset id', error: err.message });
    }
    // --- END ---

    // Basic validation for required fields (prevent NULL inserts)
    const missing = [];
    if (audit_id == null) missing.push('audit_id');
    if (asset_id == null) missing.push('asset_id');
    if (missing.length > 0) {
        console.warn('   ⚠️ Missing required fields:', missing.join(', '));
        return res.status(400).json({ message: 'Missing required fields', missing });
    }

    try {
        // --- VALIDATION: Check if audit_id and asset_id exist ---
        const [auditCheck] = await execQuery('SELECT id, location_id FROM audits WHERE id = ?', [audit_id]);
        if (auditCheck.length === 0) {
            console.warn(`   ⚠️ Audit ID ${audit_id} does not exist`);
            return res.status(404).json({ message: 'Audit not found', audit_id });
        }
        console.log(`   ✅ Audit ID ${audit_id} exists`);

        // audit_results.actual_location_id and checked_by are NOT NULL. Fall back
        // to the audit's location, and never insert a null checked_by.
        const hasLocation = actual_location_id !== undefined && actual_location_id !== null && actual_location_id !== '';
        const effectiveLocationId = hasLocation ? actual_location_id : auditCheck[0].location_id;
        const effectiveCheckedBy = (checked_by === undefined || checked_by === null) ? '' : checked_by;
        const effectiveAssetFound = (asset_found === undefined || asset_found === null) ? 1 : asset_found;

        const [assetCheck] = await execQuery('SELECT id FROM assets WHERE id = ?', [asset_id]);
        if (assetCheck.length === 0) {
            console.warn(`   ⚠️ Asset ID ${asset_id} does not exist`);
            return res.status(404).json({ message: 'Asset not found', asset_id });
        }
        console.log(`   ✅ Asset ID ${asset_id} exists`);

        // --- CHECK IF AUDIT RESULT ALREADY EXISTS ---
        const [existingResult] = await execQuery(
            'SELECT id FROM audit_results WHERE audit_id = ? AND asset_id = ?',
            [audit_id, asset_id]
        );

        const values = [
            effectiveAssetFound, actual_user || null, effectiveLocationId,
            is_physical_good, is_patch_latest, is_endpoint_latest,
            is_monitor_working, is_ups_working,
            (led_normal === undefined ? null : led_normal),
            (no_fault === undefined ? null : no_fault),
            (fa_tagging === undefined ? null : fa_tagging),
            additional_info, effectiveCheckedBy
        ];

        const sanitizedValues = values.map(v => (typeof v === 'undefined' ? null : v));

        if (existingResult.length > 0) {
            // --- UPDATE EXISTING AUDIT RESULT ---
            const existingId = existingResult[0].id;
            const updateQuery = `
                UPDATE audit_results
                SET asset_found = ?, actual_user = ?, actual_location_id = ?,
                    is_physical_good = ?, is_patch_latest = ?, is_endpoint_latest = ?,
                    is_monitor_working = ?, is_ups_working = ?, led_normal = ?, no_fault = ?, fa_tagging = ?,
                    additional_info = ?, checked_by = ?, checked_at = NOW()
                WHERE id = ?
            `;

            const updateValues = [...sanitizedValues, existingId];
            console.log('   🔄 UPDATE Query - SANITIZED VALUES:', updateValues);

            const [updateResult] = await execQuery(updateQuery, updateValues);
            console.log(`   ⬅️ STATUS: 200 OK. Audit Result updated. ID: ${existingId}`);
            return res.status(200).json({
                message: 'Audit results updated successfully.',
                id: existingId,
                action: 'updated'
            });

        } else {
            // --- CREATE NEW AUDIT RESULT ---
            const insertQuery = `
                INSERT INTO audit_results
                (audit_id, asset_id, asset_found, actual_user, actual_location_id,
                 is_physical_good, is_patch_latest, is_endpoint_latest,
                 is_monitor_working, is_ups_working, led_normal, no_fault, fa_tagging, additional_info, checked_by, checked_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW())
            `;

            const insertValues = [audit_id, asset_id, ...sanitizedValues];
            console.log('   📝 INSERT Query - SANITIZED VALUES:', insertValues);

            const [insertResult] = await execQuery(insertQuery, insertValues);
            console.log(`   ⬅️ STATUS: 201 Created. New Audit Result ID: ${insertResult.insertId}`);
            return res.status(201).json({
                message: 'Audit results submitted successfully.',
                id: insertResult.insertId,
                action: 'created'
            });
        }

    } catch (error) {
        // LOG: Error details and code, include query and bind values for debugging
        console.error('   ❌ ERROR:', error.code, error.message);
        
        if (error.code === 'ER_NO_REFERENCED_ROW_2') {
             return res.status(400).json({ message: 'Invalid audit or asset ID provided.', error: error.message });
        }
        return res.status(500).json({ message: 'Failed to submit audit results.', error: error.message });
    }
});

