// 1b. POST: Create a new asset
app.post('/api/assets', async (req, res) => {
    const data = req.body || {};

    const timestamp = new Date().toISOString();
    const clientIp = req.headers['x-forwarded-for'] || (req.socket && req.socket.remoteAddress) || req.ip || 'unknown';
    console.log(`\n[${timestamp}] POST /api/assets from ${clientIp}`);
    try { console.log('   HEADERS:', JSON.stringify(req.headers)); } catch (e) {}
    try { console.log('   RAW BODY:', JSON.stringify(req.body)); } catch (e) {}

    const {
        glpi_id, asset_tag, serial_number, model,
        assigned_user, location_id, glpi_import_date
    } = data;

    // GLPI purchase/commission date for the aging bar. Normalise GLPI's
    // '0000-00-00' and empty strings to null so COALESCE keeps any existing value.
    let date_buy = data.date_buy;
    if (!date_buy || /^0000-00-00/.test(String(date_buy))) date_buy = null;

    // Map GLPI item types that aren't first-class asset categories onto one the
    // assets table accepts (e.g. a GLPI NetworkEquipment is stored as Peripheral).
    const CATEGORY_ALIASES = { NetworkEquipment: 'Peripheral' };
    const category = CATEGORY_ALIASES[data.category] || data.category;

    // basic validation
    const missing = [];
    if (!asset_tag) missing.push('asset_tag');
    if (!category) missing.push('category');
    if (missing.length > 0) {
        console.warn('   ⚠️ Missing required fields:', missing.join(', '));
        return res.status(400).json({ message: 'Missing required fields', missing });
    }

    // validate category enum
    const allowed = ['Desktop','Laptop','Monitor','Printer','UPS','Computer','Peripheral'];
    if (!allowed.includes(category)) {
        return res.status(400).json({ message: 'Invalid category', allowed });
    }

    try {
        // Match ONLY by asset_tag — the one key that uniquely identifies a
        // physical asset. Do NOT fall back to glpi_id: GLPI ids are unique only
        // within an item type (a NetworkEquipment, a Computer and a Peripheral
        // can all be id 5), so matching by glpi_id overwrote unrelated assets —
        // e.g. a scanned network device landing on a computer's row. If the tag
        // isn't found we INSERT a new asset instead of guessing.
        let existingAsset = null;
        console.log(`   Checking if asset exists with asset_tag: ${asset_tag}`);
        const [existingRows] = await execQuery('SELECT id FROM assets WHERE asset_tag = ?', [asset_tag]);

        if (existingRows.length > 0) {
            existingAsset = existingRows[0];
            console.log(`   ✅ Asset found with ID: ${existingAsset.id}. Will UPDATE the existing record.`);
        }

        if (existingAsset) {
            // UPDATE existing asset non-destructively: COALESCE keeps the current
            // value whenever the caller sends null, so imported data (and NOT NULL
            // columns) are never clobbered.
            const updateQuery = `
                UPDATE assets
                SET glpi_id = COALESCE(?, glpi_id),
                    asset_tag = COALESCE(?, asset_tag),
                    serial_number = COALESCE(?, serial_number),
                    model = COALESCE(?, model),
                    category = COALESCE(?, category),
                    assigned_user = COALESCE(?, assigned_user),
                    location_id = COALESCE(?, location_id),
                    glpi_import_date = COALESCE(?, glpi_import_date),
                    date_buy = COALESCE(?, date_buy)
                WHERE id = ?
            `;
            const updateParams = [
                glpi_id ?? null, asset_tag ?? null, serial_number ?? null, model ?? null,
                category ?? null, assigned_user ?? null, location_id ?? null, glpi_import_date ?? null,
                date_buy ?? null,
                existingAsset.id
            ];
            await execQuery(updateQuery, updateParams);
            console.log(`   ⬅️ STATUS: 200 OK. Asset updated with ID: ${existingAsset.id}`);
            return res.status(200).json({
                message: 'Asset updated successfully',
                id: existingAsset.id,
                action: 'updated'
            });
        } else {
            // CREATE new asset. assets has NOT NULL text columns, so fall back to
            // empty strings for anything GLPI didn't provide.
            const insertValues = [
                glpi_id != null ? glpi_id : 0,
                asset_tag,
                serial_number != null ? serial_number : '',
                model != null ? model : '',
                category,
                assigned_user != null ? assigned_user : '',
                location_id != null ? location_id : null,
                glpi_import_date || null,
                date_buy || null
            ];
            const insertQuery = `
                INSERT INTO assets
                (glpi_id, asset_tag, serial_number, model, category, assigned_user, location_id, glpi_import_date, date_buy)
                VALUES (?, ?, ?, ?, ?, ?, ?, COALESCE(?, NOW()), ?)
            `;
            const [result] = await execQuery(insertQuery, insertValues);
            console.log(`   ⬅️ STATUS: 201 Created. New Asset ID: ${result.insertId}`);
            return res.status(201).json({
                message: 'Asset created successfully',
                id: result.insertId,
                action: 'created'
            });
        }
    } catch (error) {
        console.error('   ❌ ERROR:', error.code, error.message);

        if (error.code === 'ER_DUP_ENTRY') {
            return res.status(409).json({ message: 'Duplicate asset (asset_tag or unique constraint)', error: error.message });
        }
        res.status(500).json({ message: 'Failed to create or update asset', error: error.message });
    }
});

// 1c. DELETE: Remove an asset by asset_tag
app.delete('/api/assets/delete/:assetTag', async (req, res) => {
    const { assetTag } = req.params;

    const timestamp = new Date().toISOString();
    const clientIp = req.headers['x-forwarded-for'] || (req.socket && req.socket.remoteAddress) || req.ip || 'unknown';
    console.log(`\n[${timestamp}] DELETE /api/assets/delete/${assetTag} from ${clientIp}`);

    // Validate asset tag
    if (!assetTag) {
        console.warn('   ⚠️ Invalid asset tag');
        return res.status(400).json({ message: 'Invalid asset tag provided' });
    }

    try {
        // First check if asset exists by asset_tag (fetch the full row to archive)
        const [existingAsset] = await execQuery('SELECT * FROM assets WHERE asset_tag = ?', [assetTag]);

        if (existingAsset.length === 0) {
            console.warn(`   ⚠️ Asset tag ${assetTag} not found`);
            return res.status(404).json({ message: 'Asset not found', asset_tag: assetTag });
        }

        const assetSnapshot = existingAsset[0];
        const assetId = existingAsset[0].id;
        console.log(`   ✅ Asset found: Tag: ${assetTag}, ID: ${assetId}`);

        // Check if asset has related audit_results
        const [relatedResults] = await execQuery('SELECT COUNT(*) as count FROM audit_results WHERE asset_id = ?', [assetId]);
        const resultCount = relatedResults[0].count;
        
        if (resultCount > 0) {
            console.warn(`   ⚠️ Asset ${assetTag} has ${resultCount} related audit result(s). Cannot delete due to foreign key constraint.`);
            return res.status(409).json({ 
                message: 'Cannot delete asset: it has related audit results', 
                asset_tag: assetTag,
                asset_id: assetId,
                related_audit_results: resultCount
            });
        }

        // Delete the asset by ID
        const [result] = await execQuery('DELETE FROM assets WHERE id = ?', [assetId]);

        if (result.affectedRows === 0) {
            console.warn(`   ⚠️ Failed to delete asset ${assetTag}`);
            return res.status(500).json({ message: 'Failed to delete asset' });
        }

        await logAudit({
            action: 'delete',
            entityType: 'asset',
            entityId: assetId,
            actor: (req.body && req.body.actor) || (req.query && req.query.actor),
            summary: `Deleted asset ${assetTag} (#${assetId})`,
            snapshot: assetSnapshot,
        });

        console.log(`   ⬅️ STATUS: 200 OK. Asset deleted. Tag: ${assetTag}, ID: ${assetId}`);
        return res.status(200).json({
            message: 'Asset deleted successfully',
            asset_tag: assetTag,
            asset_id: assetId,
            action: 'deleted'
        });

    } catch (error) {
        console.error('   ❌ ERROR:', error.code, error.message);
        
        if (error.code === 'ER_NO_REFERENCED_ROW_2' || error.code === 'ER_ROW_IS_REFERENCED') {
            return res.status(409).json({ 
                message: 'Cannot delete asset: foreign key constraint violation',
                error: error.message 
            });
        }
        
        res.status(500).json({ message: 'Failed to delete asset', error: error.message });
    }
});

