// PUT /api/forms/:id — edit fields and/or advance status (logs each transition).
app.put('/api/forms/:id', async (req, res) => {
    const id = req.params.id;
    const b = req.body || {};
    try {
        const [existingRows] = await execQuery('SELECT * FROM forms WHERE id = ? LIMIT 1', [id]);
        if (existingRows.length === 0) return res.status(404).json({ message: 'Form not found' });
        const before = existingRows[0];

        let newStatus = before.status;
        if (b.status != null && String(b.status).trim() !== '') {
            if (!FORM_STATUSES.includes(b.status)) {
                return res.status(400).json({ message: 'Invalid status', allowed: FORM_STATUSES });
            }
            newStatus = b.status;
        }

        const receivedDate = b.received_date !== undefined ? sanitizeDate(b.received_date) : before.received_date;
        await execQuery(
            `UPDATE forms
                SET form_type = ?, reference_no = ?, received_date = ?, from_party = ?, company = ?, remarks = ?, status = ?
              WHERE id = ?`,
            [
                b.form_type !== undefined ? (b.form_type || null) : before.form_type,
                b.reference_no !== undefined ? (b.reference_no || null) : before.reference_no,
                receivedDate,
                b.from_party !== undefined ? (b.from_party || null) : before.from_party,
                b.company !== undefined ? (b.company || null) : before.company,
                b.remarks !== undefined ? (b.remarks || null) : before.remarks,
                newStatus,
                id,
            ]
        );

        // Completion warning (WARN-ONLY): when moving to Completed and the template
        // requires a signature that wasn't detected, allow it but flag a warning.
        let warning = null;
        if (newStatus === 'Completed' && newStatus !== before.status) {
            const template = resolveTemplate(b.form_type !== undefined ? b.form_type : before.form_type);
            const required = template.requiredForComplete || [];
            if (required.length) {
                const [sigs] = await execQuery(
                    'SELECT signer_label, detected FROM form_signatures WHERE form_id = ?', [id]
                );
                const missing = required.filter((label) =>
                    !sigs.some((s) => s.signer_label === label && s.detected));
                if (missing.length) {
                    warning = `Completed without a detected signature for: ${missing.join(', ')}. Verify the scan manually.`;
                }
            }
        }

        if (newStatus !== before.status) {
            const note = b.note || (warning ? '⚠ ' + warning : null);
            await execQuery(
                'INSERT INTO form_status_history (form_id, from_status, to_status, actor, note) VALUES (?, ?, ?, ?, ?)',
                [id, before.status, newStatus, b.actor || null, note]
            );
            await logAudit({
                action: 'status', entityType: 'form', entityId: id, actor: b.actor || null,
                summary: `Form ${id}: ${before.status} → ${newStatus}`,
                changes: { status: [before.status, newStatus] },
            });
        }

        return res.status(200).json({ message: 'Form updated', id: Number(id), status: newStatus, warning });
    } catch (e) {
        console.error('   ❌ update form error:', e && e.message);
        return res.status(500).json({ message: 'Failed to update form', error: e.message });
    }
});

// DELETE /api/forms/:id — archive a snapshot to audit_trail, delete images + row.
app.delete('/api/forms/:id', async (req, res) => {
    const id = req.params.id;
    const actor = (req.query.actor || (req.body && req.body.actor) || null);
    try {
        const [rows] = await execQuery('SELECT * FROM forms WHERE id = ? LIMIT 1', [id]);
        if (rows.length === 0) return res.status(404).json({ message: 'Form not found' });
        const snapshot = rows[0];

        const [imgRows] = await execQuery('SELECT img_dir FROM form_images WHERE form_id = ?', [id]);
        const images = imgRows.map((r) => r.img_dir).filter(Boolean);

        await logAudit({
            action: 'delete', entityType: 'form', entityId: id, actor,
            summary: `Deleted form ${id}${snapshot.reference_no ? ' (' + snapshot.reference_no + ')' : ''}`,
            snapshot: { ...snapshot, images },
        });

        // Remove image files (confined to the uploads dir).
        const uploadsRoot = path.resolve(uploadDir);
        for (const rel of images) {
            try {
                const abs = path.resolve(__dirname, rel);
                if (abs.startsWith(uploadsRoot + path.sep) && fs.existsSync(abs)) fs.unlinkSync(abs);
            } catch (e) { console.warn('   ⚠️ could not unlink form image:', e && e.message); }
        }

        await execQuery('DELETE FROM form_status_history WHERE form_id = ?', [id]);
        await execQuery('DELETE FROM form_images WHERE form_id = ?', [id]);
        await execQuery('DELETE FROM forms WHERE id = ?', [id]);

        return res.status(200).json({ message: 'Form deleted', id: Number(id) });
    } catch (e) {
        console.error('   ❌ delete form error:', e && e.message);
        return res.status(500).json({ message: 'Failed to delete form', error: e.message });
    }
});

// POST: Upload audit image
app.post('/api/audit/upload-image', upload.single('image'), async (req, res) => {
    const timestamp = new Date().toISOString();
    const clientIp = req.headers['x-forwarded-for'] || (req.socket && req.socket.remoteAddress) || req.ip || 'unknown';
    console.log(`\n[${timestamp}] POST /api/audit/upload-image from ${clientIp}`);

    try {
        if (!req.file) {
            console.warn('   ⚠️ No file uploaded');
            return res.status(400).json({ message: 'No image file provided' });
        }

        const { audit_result_id, computer_name, asset_id } = req.body;

        // Require at least one: audit_result_id OR asset_id OR computer_name
        if (!audit_result_id && !asset_id && !computer_name) {
            console.warn('   ⚠️ Missing required fields: audit_result_id OR asset_id OR computer_name');
            return res.status(400).json({ message: 'Missing required field: provide audit_result_id or asset_id or computer_name' });
        }

        // Construct the folder and relative image path (current filename)
        const now = new Date();
        const year = now.getFullYear();
        const month = String(now.getMonth() + 1).padStart(2, '0');
        const day = String(now.getDate()).padStart(2, '0');
        const folderPath = `uploads/${year}${month}${day}`;
        const oldFilename = req.file.filename;
        const oldFullPath = req.file.path;

        console.log(`   📁 Image saved to: ${oldFullPath}`);
        console.log(`   📸 Original filename: ${oldFilename}`);

        // Helper sanitize (match storage.filename sanitize)
        const sanitize = (s) => {
            if (s === undefined || s === null || s === '') return 'UNKNOWN';
            return String(s)
                .trim()
                .replace(/\s+/g, '_')
                .replace(/[^a-zA-Z0-9-_]/g, '_')
                .toUpperCase()
                .slice(0, 50);
        };

        // Resolve desired base name: computer_name > asset.serial_number (by asset_id) > asset.serial_number (by audit_result_id)
        let finalBase = null;
        if (computer_name) {
            finalBase = sanitize(computer_name);
        } else if (asset_id) {
            try {
                const [rows] = await execQuery('SELECT serial_number FROM assets WHERE id = ? LIMIT 1', [asset_id]);
                const serial = (rows && rows[0] && rows[0].serial_number) ? rows[0].serial_number : null;
                finalBase = sanitize(serial || asset_id);
            } catch (err) {
                console.error('   ❌ ERROR resolving serial_number by asset_id after upload:', err && err.message);
                finalBase = sanitize(asset_id);
            }
        } else if (audit_result_id) {
            try {
                const [rows] = await execQuery(
                    'SELECT a.serial_number FROM assets a LEFT JOIN audit_results ar ON a.id = ar.asset_id WHERE ar.id = ? LIMIT 1',
                    [audit_result_id]
                );
                const serial = (rows && rows[0] && rows[0].serial_number) ? rows[0].serial_number : null;
                finalBase = sanitize(serial || audit_result_id);
            } catch (err) {
                console.error('   ❌ ERROR resolving serial_number by audit_result_id after upload:', err && err.message);
                finalBase = sanitize(audit_result_id);
            }
        } else {
            finalBase = 'UNKNOWN';
        }

        // Build new filename with date and timestamp
        const dd = String(now.getDate()).padStart(2, '0');
        const mm = String(now.getMonth() + 1).padStart(2, '0');
        const yy = String(now.getFullYear()).slice(-2);
        const hh = String(now.getHours()).padStart(2, '0');
        const min = String(now.getMinutes()).padStart(2, '0');
        const ss = String(now.getSeconds()).padStart(2, '0');
        // Include milliseconds + a short random so multiple photos for the same
        // audit result never collide / overwrite each other.
        const ms = String(now.getMilliseconds()).padStart(3, '0');
        const rand = Math.random().toString(36).slice(2, 6);
        const time = `${hh}${min}${ss}${ms}_${rand}`;
        const ext = path.extname(oldFilename) || path.extname(req.file.originalname) || '';
        const newFilename = audit_result_id ? `${finalBase}_AR${audit_result_id}_${dd}${mm}${yy}_${time}${ext}` : `${finalBase}_${dd}${mm}${yy}_${time}${ext}`;
        const newFullPath = path.join(path.dirname(oldFullPath), newFilename);

        try {
            await fs.promises.rename(oldFullPath, newFullPath);
            console.log(`   🔁 Renamed file to: ${newFullPath}`);
        } catch (err) {
            console.error('   ❌ ERROR renaming uploaded file:', err && err.message);
            // If rename fails, continue but report original filename
        }

        const imgPath = `${folderPath}/${newFilename}`;
        console.log(`   💾 DB path: ${imgPath}`);

        // Update audit_results table with image path if audit_result_id provided
        if (audit_result_id) {
            const updateQuery = `
                UPDATE audit_results
                SET img_dir = ?
                WHERE id = ?
            `;
            const [result] = await execQuery(updateQuery, [imgPath, audit_result_id]);
            if (result.affectedRows === 0) {
                console.warn(`   ⚠️ Audit result ID ${audit_result_id} not found`);
                return res.status(404).json({ message: 'Audit result not found' });
            }

            // Record this photo so multiple images per audit result are kept.
            try {
                await execQuery(
                    'INSERT INTO audit_result_images (audit_result_id, img_dir) VALUES (?, ?)',
                    [audit_result_id, imgPath]
                );
            } catch (e) {
                console.error('   ❌ ERROR recording audit_result_images row:', e && e.message);
            }

            console.log(`   ⬅️ STATUS: 200 OK. Image uploaded and audit_result updated`);
            return res.status(200).json({
                message: 'Image uploaded successfully',
                file: {
                    filename: newFilename,
                    originalName: req.file.originalname,
                    size: req.file.size,
                    path: imgPath,
                    fullPath: newFullPath
                },
                updated_audit_result_id: audit_result_id
            });
        }

        // If no audit_result_id provided, return file info (DB not updated)
        return res.status(200).json({
            message: 'Image uploaded successfully (DB not updated - no audit_result_id provided)',
            file: {
                filename: newFilename,
                originalName: req.file.originalname,
                size: req.file.size,
                path: imgPath,
                fullPath: newFullPath
            }
        });

    } catch (error) {
        console.error('   ❌ ERROR uploading image:', error.message);
        return res.status(500).json({
            message: 'Failed to upload image',
            error: error.message
        });
    }
});

// GET: List scanned items for a specific audit (audit_id)
app.get('/api/audit/:auditId/scanned-items', async (req, res) => {
    const auditId = req.params.auditId;
    const timestamp = new Date().toISOString();
    const clientIp = req.headers['x-forwarded-for'] || (req.socket && req.socket.remoteAddress) || req.ip || 'unknown';
    console.log(`\n[${timestamp}] GET /api/audit/${auditId}/scanned-items from ${clientIp}`);

    if (!auditId) {
        return res.status(400).json({ message: 'Missing auditId parameter' });
    }

    // optional pagination
    const limit = Math.min(parseInt(req.query.limit) || 100, 1000);
    const offset = parseInt(req.query.offset) || 0;

    const query = `
        SELECT 
            ar.id AS audit_result_id,
            ar.audit_id,
            ar.asset_id,
            a.asset_tag,
            a.serial_number,
            a.model,
            a.category,
            a.date_buy,
            a.assigned_user AS assigned_user,
            ar.asset_found,
            ar.actual_user,
            ar.actual_location_id,
            ar.is_physical_good,
            ar.is_patch_latest,
            ar.is_endpoint_latest,
            ar.is_monitor_working,
            ar.is_ups_working,
            ar.led_normal,
            ar.no_fault,
            ar.fa_tagging,
            ar.additional_info,
            ar.checked_by,
            ar.checked_at,
            ar.img_dir,
            (SELECT GROUP_CONCAT(ari.img_dir SEPARATOR '||')
               FROM audit_result_images ari WHERE ari.audit_result_id = ar.id) AS images
        FROM audit_results ar
        LEFT JOIN assets a ON a.id = ar.asset_id
        WHERE ar.audit_id = ?
        ORDER BY ar.checked_at DESC, ar.id DESC
        LIMIT ? OFFSET ?
    `;

    try {
        const [rows] = await execQuery(query, [auditId, limit, offset]);
        console.log(`   ⬅️ STATUS: 200 OK. Returned ${rows.length} scanned items for audit ${auditId}`);
        return res.status(200).json({
            audit_id: auditId,
            returned: rows.length,
            limit,
            offset,
            data: rows
        });
    } catch (error) {
        console.error('   ❌ ERROR fetching scanned items:', error && error.message);
        return res.status(500).json({ message: 'Failed to retrieve scanned items', error: error && error.message });
    }
});

// GET: Serve the uploaded audit photo for a given audit_result id
app.get('/api/audit/result/:auditResultId/image', async (req, res) => {
    const auditResultId = req.params.auditResultId;
    const timestamp = new Date().toISOString();
    const clientIp = req.headers['x-forwarded-for'] || (req.socket && req.socket.remoteAddress) || req.ip || 'unknown';
    console.log(`\n[${timestamp}] GET /api/audit/result/${auditResultId}/image from ${clientIp}`);

    if (!auditResultId) {
        return res.status(400).json({ message: 'Missing auditResultId parameter' });
    }

    try {
        const [rows] = await execQuery('SELECT img_dir FROM audit_results WHERE id = ?', [auditResultId]);

        if (rows.length === 0) {
            console.warn(`   ⚠️ Audit result ${auditResultId} not found`);
            return res.status(404).json({ message: 'Audit result not found' });
        }

        const imgDir = rows[0].img_dir;
        if (!imgDir) {
            console.warn(`   ⚠️ Audit result ${auditResultId} has no image`);
            return res.status(404).json({ message: 'No image for this audit result' });
        }

        // Resolve to an absolute path and guard against path traversal so only
        // files inside the uploads directory can ever be served.
        const absolutePath = path.resolve(__dirname, imgDir);
        const uploadsRoot = path.resolve(uploadDir);
        if (!absolutePath.startsWith(uploadsRoot + path.sep)) {
            console.error(`   ❌ Rejected image path outside uploads: ${absolutePath}`);
            return res.status(400).json({ message: 'Invalid image path' });
        }

        if (!fs.existsSync(absolutePath)) {
            console.warn(`   ⚠️ Image file missing on disk: ${absolutePath}`);
            return res.status(404).json({ message: 'Image file not found on disk', path: imgDir });
        }

        console.log(`   ⬅️ STATUS: 200 OK. Sending image: ${imgDir}`);
        return res.sendFile(absolutePath);
    } catch (error) {
        console.error('   ❌ ERROR serving audit image:', error && error.message);
        return res.status(500).json({ message: 'Failed to serve audit image', error: error && error.message });
    }
});

// GET: List ALL photos for a given audit_result id.
// Reads from the audit_result_images table (one row per uploaded photo). Falls
// back to a disk scan + the single img_dir for records created before the table
// existed.
app.get('/api/audit/result/:auditResultId/images', async (req, res) => {
    const rawId = req.params.auditResultId;
    const auditResultId = parseInt(rawId, 10);
    const timestamp = new Date().toISOString();
    const clientIp = req.headers['x-forwarded-for'] || (req.socket && req.socket.remoteAddress) || req.ip || 'unknown';
    console.log(`\n[${timestamp}] GET /api/audit/result/${rawId}/images from ${clientIp}`);

    if (!Number.isInteger(auditResultId) || auditResultId <= 0) {
        return res.status(400).json({ message: 'Invalid auditResultId parameter' });
    }

    const toImage = (imgDir) => {
        const rel = String(imgDir).replace(/^\/+/, '').replace(/^uploads[\\/]/, '');
        return { path: `uploads/${rel}`, url: `/uploads/${rel}` };
    };

    try {
        // 1) Primary source: the audit_result_images table.
        const seen = new Set();
        const images = [];
        try {
            const [rows] = await execQuery(
                'SELECT img_dir FROM audit_result_images WHERE audit_result_id = ? ORDER BY id',
                [auditResultId]
            );
            for (const r of rows) {
                if (!r.img_dir) continue;
                const img = toImage(r.img_dir);
                if (!seen.has(img.url)) { seen.add(img.url); images.push(img); }
            }
        } catch (e) {
            console.warn('   ⚠️ Could not read audit_result_images:', e && e.message);
        }

        // 2) Legacy fallback (records from before the table): disk scan + img_dir.
        if (images.length === 0) {
            let primary = null;
            try {
                const [rows] = await execQuery('SELECT img_dir FROM audit_results WHERE id = ?', [auditResultId]);
                if (rows.length > 0 && rows[0].img_dir) primary = String(rows[0].img_dir);
            } catch (e) {
                console.warn('   ⚠️ Could not read img_dir:', e && e.message);
            }

            let entries = [];
            try {
                entries = fs.readdirSync(uploadDir, { recursive: true });
            } catch (e) {
                console.warn('   ⚠️ Could not read uploads dir:', e && e.message);
            }
            const marker = new RegExp(`_AR${auditResultId}_`);
            for (const entry of entries) {
                if (typeof entry === 'string' && marker.test(path.basename(entry))) {
                    const img = toImage(String(entry).split(path.sep).join('/'));
                    if (!seen.has(img.url)) { seen.add(img.url); images.push(img); }
                }
            }
            if (primary) {
                const img = toImage(primary);
                if (!seen.has(img.url)) { seen.add(img.url); images.push(img); }
            }
        }

        console.log(`   ⬅️ STATUS: 200 OK. ${images.length} image(s) for audit_result ${auditResultId}`);
        return res.status(200).json({
            audit_result_id: auditResultId,
            count: images.length,
            images
        });
    } catch (error) {
        console.error('   ❌ ERROR listing audit images:', error && error.message);
        return res.status(500).json({ message: 'Failed to list audit images', error: error && error.message });
    }
});

// PUT: Edit an existing audit result (e.g. correct a wrong location from the
// web dashboard). Updates only the fields provided; never changes checked_at
// (the original scan time) or the asset it points to.
app.put('/api/audit/result/:id', async (req, res) => {
    const id = parseInt(req.params.id, 10);
    const data = req.body || {};

    const timestamp = new Date().toISOString();
    const clientIp = req.headers['x-forwarded-for'] || (req.socket && req.socket.remoteAddress) || req.ip || 'unknown';
    console.log(`\n[${timestamp}] PUT /api/audit/result/${req.params.id} from ${clientIp}`);
    try { console.log('   RAW BODY:', JSON.stringify(req.body)); } catch (e) {}

    if (!Number.isInteger(id) || id <= 0) {
        return res.status(400).json({ message: 'Invalid audit result id' });
    }

    // actual_location_id and checked_by are NOT NULL — reject blanking them.
    if (Object.prototype.hasOwnProperty.call(data, 'actual_location_id') &&
        (data.actual_location_id === null || data.actual_location_id === '')) {
        return res.status(400).json({ message: 'actual_location_id cannot be empty' });
    }

    const allowed = [
        'asset_found', 'actual_user', 'actual_location_id',
        'is_physical_good', 'is_patch_latest', 'is_endpoint_latest',
        'is_monitor_working', 'is_ups_working', 'led_normal', 'no_fault', 'fa_tagging', 'additional_info', 'checked_by'
    ];
    // Columns that accept NULL when the caller sends an empty value.
    const nullable = new Set(['actual_user', 'additional_info', 'fa_tagging']);

    const sets = [];
    const values = [];
    for (const key of allowed) {
        if (!Object.prototype.hasOwnProperty.call(data, key)) continue;
        let v = data[key];
        if (v === '' && nullable.has(key)) v = null;
        sets.push(`${key} = ?`);
        values.push(v);
    }

    if (sets.length === 0) {
        return res.status(400).json({ message: 'No editable fields provided' });
    }

    try {
        const [existsRows] = await execQuery('SELECT * FROM audit_results WHERE id = ?', [id]);
        if (existsRows.length === 0) {
            return res.status(404).json({ message: 'Audit result not found', id });
        }
        const before = existsRows[0];
        values.push(id);
        await execQuery(`UPDATE audit_results SET ${sets.join(', ')} WHERE id = ?`, values);

        // Record a field-level diff of what actually changed.
        const changes = {};
        for (const key of allowed) {
            if (!Object.prototype.hasOwnProperty.call(data, key)) continue;
            let v = data[key];
            if (v === '' && nullable.has(key)) v = null;
            const oldVal = before[key];
            if (String(oldVal ?? '') !== String(v ?? '')) {
                changes[key] = { old: oldVal ?? null, new: v ?? null };
            }
        }
        if (Object.keys(changes).length > 0) {
            await logAudit({
                action: 'update',
                entityType: 'audit_result',
                entityId: id,
                actor: data.actor,
                summary: `Edited audit result #${id} (${Object.keys(changes).join(', ')})`,
                changes,
            });
        }

        console.log(`   ⬅️ STATUS: 200 OK. Audit result ${id} updated (${sets.length} field(s)).`);
        return res.status(200).json({ message: 'Audit result updated', id, action: 'updated' });
    } catch (error) {
        console.error('   ❌ ERROR updating audit result:', error.code, error.message);
        return res.status(500).json({ message: 'Failed to update audit result', error: error.message });
    }
});

// DELETE: Remove a whole scanned audit result. The full row (plus its photo
// list) is archived to audit_trail first, so nothing is truly lost — you can
// see exactly what was deleted. Its photo files are removed from disk.
app.delete('/api/audit/result/:id', async (req, res) => {
    const id = parseInt(req.params.id, 10);
    const timestamp = new Date().toISOString();
    console.log(`\n[${timestamp}] DELETE /api/audit/result/${req.params.id}`);

    if (!Number.isInteger(id) || id <= 0) {
        return res.status(400).json({ message: 'Invalid audit result id' });
    }

    try {
        const [rows] = await execQuery('SELECT * FROM audit_results WHERE id = ?', [id]);
        if (rows.length === 0) {
            return res.status(404).json({ message: 'Audit result not found', id });
        }
        const snapshot = rows[0];

        const [imgRows] = await execQuery('SELECT img_dir FROM audit_result_images WHERE audit_result_id = ?', [id]);
        const images = imgRows.map(r => r.img_dir).filter(Boolean);
        if (snapshot.img_dir && !images.includes(snapshot.img_dir)) images.push(snapshot.img_dir);

        // Remove photo files from disk (best-effort, confined to uploads).
        for (const img of images) {
            const abs = path.resolve(__dirname, String(img).replace(/\\/g, '/'));
            if (abs.startsWith(path.resolve(uploadDir))) {
                await fs.promises.unlink(abs).catch(() => {});
            }
        }

        // audit_result_images has ON DELETE CASCADE, but delete explicitly too.
        await execQuery('DELETE FROM audit_result_images WHERE audit_result_id = ?', [id]);
        await execQuery('DELETE FROM audit_results WHERE id = ?', [id]);

        await logAudit({
            action: 'delete',
            entityType: 'audit_result',
            entityId: id,
            actor: (req.body && req.body.actor) || (req.query && req.query.actor),
            summary: `Deleted audit result #${id} (asset_id ${snapshot.asset_id}, audit ${snapshot.audit_id})`,
            snapshot: { ...snapshot, images },
        });

        console.log(`   ⬅️ STATUS: 200 OK. Deleted audit result ${id} (archived).`);
        return res.status(200).json({ message: 'Audit result deleted', id, action: 'deleted' });
    } catch (error) {
        console.error('   ❌ ERROR deleting audit result:', error.code, error.message);
        return res.status(500).json({ message: 'Failed to delete audit result', error: error.message });
    }
});

// GET: Read the audit trail (updates + deletions), newest first.
app.get('/api/audit-trail', async (req, res) => {
    const limit = Math.min(parseInt(req.query.limit) || 200, 1000);
    const offset = parseInt(req.query.offset) || 0;
    const action = (req.query.action || '').toString();
    const entityType = (req.query.entity_type || '').toString();

    const where = [];
    const params = [];
    if (action) { where.push('action = ?'); params.push(action); }
    if (entityType) { where.push('entity_type = ?'); params.push(entityType); }
    const whereSql = where.length ? 'WHERE ' + where.join(' AND ') : '';

    try {
        const [rows] = await execQuery(
            `SELECT id, action, entity_type, entity_id, actor, summary, changes, snapshot, created_at
             FROM audit_trail ${whereSql} ORDER BY id DESC LIMIT ? OFFSET ?`,
            [...params, limit, offset]
        );
        // Parse the JSON text columns back to objects for the client.
        const data = rows.map(r => ({
            ...r,
            changes: r.changes ? safeParse(r.changes) : null,
            snapshot: r.snapshot ? safeParse(r.snapshot) : null,
        }));
        return res.status(200).json({ returned: data.length, limit, offset, data });
    } catch (error) {
        console.error('   ❌ ERROR reading audit trail:', error && error.message);
        return res.status(500).json({ message: 'Failed to read audit trail', error: error.message });
    }
});

function safeParse(s) { try { return JSON.parse(s); } catch (e) { return s; } }

// DELETE: Remove one photo from an audit result — deletes the file on disk and
// its DB rows. Only touches files inside the uploads dir that belong to this
// result (matched by basename), so it can't be used to delete arbitrary files.
app.delete('/api/audit/result/:id/image', async (req, res) => {
    const id = parseInt(req.params.id, 10);
    const body = req.body || {};
    const rawPath = (body.path || body.img_dir || '').toString();

    const timestamp = new Date().toISOString();
    console.log(`\n[${timestamp}] DELETE /api/audit/result/${req.params.id}/image path=${rawPath}`);

    if (!Number.isInteger(id) || id <= 0) {
        return res.status(400).json({ message: 'Invalid audit result id' });
    }
    if (!rawPath) {
        return res.status(400).json({ message: 'Missing image path' });
    }

    const base = path.basename(rawPath.replace(/\\/g, '/'));
    if (!base || base === '.' || base === '..') {
        return res.status(400).json({ message: 'Invalid image path' });
    }

    try {
        // Locate the stored img_dir (in audit_result_images or the legacy column)
        // whose basename matches — this both authorizes and resolves the delete.
        let target = null;
        const [imgRows] = await execQuery(
            'SELECT img_dir FROM audit_result_images WHERE audit_result_id = ?',
            [id]
        );
        for (const r of imgRows) {
            if (r.img_dir && path.basename(String(r.img_dir)) === base) { target = String(r.img_dir); break; }
        }

        let legacy = null;
        const [arRows] = await execQuery('SELECT img_dir FROM audit_results WHERE id = ?', [id]);
        if (arRows.length && arRows[0].img_dir) legacy = String(arRows[0].img_dir);
        if (!target && legacy && path.basename(legacy) === base) target = legacy;

        if (!target) {
            return res.status(404).json({ message: 'Image not found for this audit result' });
        }

        // Remove the gallery rows for this file.
        await execQuery(
            'DELETE FROM audit_result_images WHERE audit_result_id = ? AND img_dir LIKE ?',
            [id, '%' + base]
        );

        // If the legacy single-image column pointed here, repoint it to a
        // remaining photo (or clear it).
        if (legacy && path.basename(legacy) === base) {
            const [remaining] = await execQuery(
                'SELECT img_dir FROM audit_result_images WHERE audit_result_id = ? ORDER BY id LIMIT 1',
                [id]
            );
            const next = remaining.length ? remaining[0].img_dir : null;
            await execQuery('UPDATE audit_results SET img_dir = ? WHERE id = ?', [next, id]);
        }

        // Delete the file, guarding against path traversal outside uploadDir.
        const abs = path.resolve(__dirname, target.replace(/\\/g, '/'));
        if (abs.startsWith(path.resolve(uploadDir))) {
            await fs.promises.unlink(abs).catch((e) => console.warn('   ⚠️ unlink failed:', e && e.message));
        } else {
            console.warn('   ⚠️ refused to unlink outside uploads:', abs);
        }

        await logAudit({
            action: 'delete',
            entityType: 'audit_result_image',
            entityId: id,
            actor: (req.body && req.body.actor) || (req.query && req.query.actor),
            summary: `Deleted photo ${base} from audit result #${id}`,
            snapshot: { audit_result_id: id, img_dir: target },
        });

        console.log(`   ⬅️ STATUS: 200 OK. Removed image ${base} from result ${id}.`);
        return res.status(200).json({ message: 'Image removed', id, file: base });
    } catch (error) {
        console.error('   ❌ ERROR deleting image:', error.code, error.message);
        return res.status(500).json({ message: 'Failed to delete image', error: error.message });
    }
});

// POST: Create a network device (router / switch) — entered manually in the app.
app.post('/api/network-devices', async (req, res) => {
    const data = req.body || {};

    const timestamp = new Date().toISOString();
    const clientIp = req.headers['x-forwarded-for'] || (req.socket && req.socket.remoteAddress) || req.ip || 'unknown';
    console.log(`\n[${timestamp}] POST /api/network-devices from ${clientIp}`);
    try { console.log('   RAW BODY:', JSON.stringify(req.body)); } catch (e) {}

    let { device_type, brand, model, ip_address, mac_address, location_id, audit_id, created_by } = data;

    // Validate device_type
    const allowedTypes = ['Router', 'Switch'];
    if (!device_type || !allowedTypes.includes(device_type)) {
        return res.status(400).json({ message: 'Invalid or missing device_type', allowed: allowedTypes });
    }

    // Require at least a model or brand to identify the device
    if ((!brand || !String(brand).trim()) && (!model || !String(model).trim())) {
        return res.status(400).json({ message: 'Provide at least a brand or model' });
    }

    // Light format validation (only when provided)
    if (ip_address && !/^(\d{1,3}\.){3}\d{1,3}$/.test(String(ip_address).trim())) {
        return res.status(400).json({ message: 'Invalid ip_address format' });
    }
    if (mac_address && !/^([0-9A-Fa-f]{2}[:-]){5}[0-9A-Fa-f]{2}$/.test(String(mac_address).trim())) {
        return res.status(400).json({ message: 'Invalid mac_address format (expected AA:BB:CC:DD:EE:FF)' });
    }

    const query = `
        INSERT INTO network_devices
        (device_type, brand, model, ip_address, mac_address, location_id, audit_id, created_by)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    `;
    const values = [
        device_type,
        brand ? String(brand).trim() : null,
        model ? String(model).trim() : null,
        ip_address ? String(ip_address).trim() : null,
        mac_address ? String(mac_address).trim().toUpperCase() : null,
        (location_id === undefined || location_id === '' ? null : location_id),
        (audit_id === undefined || audit_id === '' ? null : audit_id),
        created_by ? String(created_by).trim() : null
    ];

    try {
        const [result] = await execQuery(query, values);
        console.log(`   ⬅️ STATUS: 201 Created. New network device ID: ${result.insertId}`);
        return res.status(201).json({ message: 'Network device created', id: result.insertId, action: 'created' });
    } catch (error) {
        console.error('   ❌ ERROR creating network device:', error.code, error.message);
        return res.status(500).json({ message: 'Failed to create network device', error: error.message });
    }
});

// GET: List network devices (optional filters: device_type, location_id, audit_id)
app.get('/api/network-devices', async (req, res) => {
    const timestamp = new Date().toISOString();
    const clientIp = req.headers['x-forwarded-for'] || (req.socket && req.socket.remoteAddress) || req.ip || 'unknown';
    console.log(`\n[${timestamp}] GET /api/network-devices from ${clientIp}`);

    const limit = Math.min(parseInt(req.query.limit) || 200, 1000);
    const offset = parseInt(req.query.offset) || 0;

    const conditions = [];
    const params = [];
    if (req.query.device_type) { conditions.push('device_type = ?'); params.push(req.query.device_type); }
    if (req.query.location_id) { conditions.push('location_id = ?'); params.push(req.query.location_id); }
    if (req.query.audit_id) { conditions.push('audit_id = ?'); params.push(req.query.audit_id); }
    const where = conditions.length ? 'WHERE ' + conditions.join(' AND ') : '';

    try {
        const [rows] = await execQuery(
            `SELECT id, device_type, brand, model, ip_address, mac_address, location_id, audit_id, created_by, created_at
             FROM network_devices ${where} ORDER BY id DESC LIMIT ? OFFSET ?`,
            [...params, limit, offset]
        );
        console.log(`   ⬅️ STATUS: 200 OK. Returned ${rows.length} network devices`);
        return res.status(200).json({ data: rows, returned: rows.length, limit, offset });
    } catch (error) {
        console.error('   ❌ ERROR fetching network devices:', error && error.message);
        return res.status(500).json({ message: 'Failed to retrieve network devices', error: error.message });
    }
});

